<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        const player = { x: 0, y: 0 };
        const tiles = {};
        const inventory = { seeds: 5, crops: 0 };
        let day = 0;

        function drawPlayer() {
            ctx.fillStyle = 'green';
            ctx.fillRect(player.x, player.y, 20, 20);
        }

        function drawTiles() {
            for (const tile in tiles) {
                const { crop, stage } = tiles[tile];
                ctx.fillStyle = crop ? 'yellow' : 'green';
                ctx.fillRect(tile.split(',')[0], tile.split(',')[1], 20, 20);
            }
        }

        function drawInventory() {
            ctx.fillStyle = 'blue';
            ctx.fillText(`Seeds: ${inventory.seeds}`, 10, 10);
            ctx.fillText(`Crops: ${inventory.crops}`, 10, 30);
        }

        function drawDay() {
            ctx.fillStyle = 'red';
            ctx.fillText(`Day: ${day}`, 10, 50);
        }

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawPlayer();
            drawTiles();
            drawInventory();
            drawDay();
            requestAnimationFrame(draw);
        }

        function movePlayer(event) {
            const dx = event.key === 'ArrowLeft' ? -10 : event.key === 'ArrowRight' ? 10 : 0;
            const dy = event.key === 'ArrowUp' ? -10 : event.key === 'ArrowDown' ? 10 : 0;
            player.x += dx;
            player.y += dy;
            if (player.x < 0 || player.x >= canvas.width || player.y < 0 || player.y >= canvas.height) {
                player.x -= dx;
                player.y -= dy;
            }
        }

        function plantSeed() {
            const tile = `${player.x},${player.y}`;
            if (!tiles[tile]) {
                tiles[tile] = { crop: 'seed', stage: 0 };
                inventory.seeds--;
            }
        }

        function advanceTime() {
            day++;
        }

        function harvestCrop() {
            const tile = `${player.x},${player.y}`;
            if (tiles[tile] && tiles[tile].crop === 'seed') {
                tiles[tile].crop = 'crop';
                inventory.crops++;
            }
        }

        function saveGame() {
            localStorage.setItem('game', JSON.stringify({ player, tiles, inventory, day }));
        }

        function loadGame() {
            const savedGame = localStorage.getItem('game');
            if (savedGame) {
                const { player, tiles, inventory, day } = JSON.parse(savedGame);
                window.game = { player, tiles, inventory, day };
            }
        }

        window.addEventListener('keydown', movePlayer);
        window.addEventListener('keydown', (event) => {
            if (event.key === 'p') {
                plantSeed();
            } else if (event.key === 't') {
                advanceTime();
            } else if (event.key === 'h') {
                harvestCrop();
            }
        });

        window.addEventListener('load', loadGame);
        draw();
    </script>
</body>
</html>
